c.python:
class Solution:
    def xorBeauty(self, nums: List[int]) -> int:
        ans = 0
        for b in range(31):
            cnt = sum((x >> b) & 1 for x in nums)
            if cnt & 1:
                ans |= 1 << b
        return ans

c.cpp:
class Solution {
public:
    int xorBeauty(vector<int>& nums) {
        int ans = 0;
        for (int b = 0; b < 31; ++b) {
            long long cnt = 0;
            for (int x : nums) cnt += (x >> b) & 1;
            if (cnt & 1) ans |= 1 << b;
        }
        return ans;
    }
};

